def solve(N, x, M, y):
    import math

    # Distance between centers
    dist = abs(x - y)

    # Count intersections between the two sets
    # For round i (radius i) and round j (radius j):
    # They intersect if dist <= r1 + r2 and dist >= |r1 - r2|

    intersections = 0

    for r1 in range(1, N + 1):
        for r2 in range(1, M + 1):
            sum_r = r1 + r2
            diff_r = abs(r1 - r2)
            if dist <= sum_r and dist >= diff_r:
                intersections += 2  # Two intersection points

    # Count how many pairs actually intersect (not nested)
    intersecting_pairs = 0
    for r1 in range(1, N + 1):
        for r2 in range(1, M + 1):
            sum_r = r1 + r2
            diff_r = abs(r1 - r2)
            if dist <= sum_r and dist >= diff_r:
                intersecting_pairs += 1

    # By Euler's formula for planar arrangements of circles:
    # Regions = 1 + (total intersections + total circles - 1)
    # When circles intersect, each intersection point adds to regions

    # For two families of non-intersecting circles, total regions = 1 + N + M + 2*intersections

    # Actually for concentric circles offset from each other:
    # The formula is: regions = N + M + 1 + 2 * (number of intersecting pairs)
    # This assumes each intersecting pair adds region divisions

    # But simpler: each circle from set 1 can intersect with circles from set 2
    # Each pair that intersects at 2 points adds 2 intersections

    # Final formula based on problem analysis:
    regions = 1 + N + M + intersections - 2 * intersecting_pairs

    # Actually this is getting complex. Let me use a cleaner approach:
    # Start with 1 region (empty plane)
    # Add N concentric circles from set 1: each adds 1 region if separated
    # Add M concentric circles from set 2: each can intersect with circle from set 1
    # Intersection points divide circles, creating more regions

    # Cleaner formula based on typical arrangements:
    # regions = 1 + N + M + number_of_intersection_pairs

    return 1 + N + M + 2 * intersecting_pairs


