    result = 0

    # For each array length r from 1 to n
    for r in range(1, n + 1):
        if r == 1:
            # Single element cannot form a good cycle with adjacent difference = 1
            continue

        if r == 2:
            # Two elements: need |a1 - a2| = 1
            # In non-decreasing form: a2 - a1 >= 0, and |a2 - a1| = 1 means a2 - a1 = 1
            # Valid non-decreasing arrays: [x, x+1] where x in [1, m-1]
            count = 0
            for x in range(1, m):
                count += 1
            if 1 <= count <= k:
                result = (result + count) % MOD

        elif r % 2 == 1:
            # Odd length: alternating pattern a, b, a, b, ..., a where |a-b| = 1
            # Need (r+1)/2 elements of one value, (r-1)/2 of another
            # For non-decreasing: smaller value comes first, then alternating
            if r == 3:
                # Pattern can be [x, x+1, x] when rearranged, must be non-decreasing [x, x, x+1]
                # Check if [x, x, x+1] can form a good cycle when rearranged
                for x in range(1, m):
                    count += 1
            else:
                # More complex for larger odd r
                count = 1
                if 1 <= k:
                    result = (result + count) % MOD

        else:
