Let me analyze this problem. It's a 2-SAT style satisfiability problem where each variable appears at most twice in the entire formula. I need to:
1. Build an implication graph from the CNF clauses
2. Check for contradictions using SCC (Strongly Connected Component) algorithm
3. If satisfiable, construct a valid assignment

The key insight for 2-SAT is:
- Each clause (l1 ∨ l2 ∨ ... ∨ lk) creates implications: ¬li → lj for all i≠j
- If any variable and its negation are in the same SCC, the formula is UNSAT
- Otherwise, it's SAT, and we can construct an assignment from the topological order of SCCs

```python
import sys

sys.setrecursionlimit(500000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "NO"

    n, m = map(int, lines[0].split())

    # Map literals to nodes:
    # Node i (0-indexed) for literal x_{i+1} (positive)
    # Node m+i for literal -x_{i+1} (negative)
    num_nodes = 2 * m

    adj = [[] for _ in range(num_nodes)]

    def lit_to_node(lit):
        """Convert literal to node index"""
        if lit > 0:
            return lit - 1  # x1->0, x2->1, etc.
        else:
            return m + abs(lit) - 1  # -x1->m, -x2->m+1, etc.

    def node_to_lit(node):
        """Convert node back to literal"""
        if node < m:
            return node + 1
        else:
            return -(node - m + 1)

    def get_neg_node(node):
        """Get node for negation of literal at node"""
        return node + m if node < m else node - m

    # Build implication graph
    for i in range(n):
        parts = list(map(int, lines[1 + i].split()))
        ki = parts[0]
        literals = parts[1:]

        # For clause (l1 OR l2 OR ... OR lk):
        # add edge ¬l1 -> l2, ¬l1 -> l3, ..., ¬l1 -> lk
        # add edge ¬l2 -> l1, ¬l2 -> l3, ..., ¬l2 -> lk
        # etc.
        nodes = [lit_to_node(lit) for lit in literals]
        for i in range(len(nodes)):
            for j in range(len(nodes)):
                if i != j:
                    u = get_neg_node(nodes[i])
                    v = nodes[j]
                    # Avoid adding self-loop (¬l -> l would be u -> u)
                    adj[u].append(v)

    # Tarjan's algorithm for SCC
    index_counter = [0]
    stack = []
    lowlink = [0] * num_nodes
    index = [0] * num_nodes
    on_stack = [False] * num_nodes
    scc_ids = [-1] * num_nodes
    scc_count = 0

    def strongconnect(node):
        index[node] = index_counter[0]
        lowlink[node] = index_counter[0]
        index_counter[0] += 1
        stack.append(node)
        on_stack[node] = True

        for neighbor in adj[node]:
            if index[neighbor] == 0:
                strongconnect(neighbor)
                lowlink[node] = min(lowlink[node], lowlink[neighbor])
            elif on_stack[neighbor]:
                lowlink[node] = min(lowlink[node], index[neighbor])

        if lowlink[node] == index[node]:
            while True:
                w = stack.pop()
                on_stack[w] = False
                scc_ids[w] = scc_count
                if w == node:
                    break
            scc_count += 1

    for i in range(num_nodes):
        if index[i] == 0:
            strongconnect(i)

    # Check satisfiability: if x_i and -x_i in same SCC, UNSAT
    for i in range(1, m + 1):
        pos_node = i - 1
        neg_node = m + i - 1
        if scc_ids[pos_node] == scc_ids[neg_node]:
            return "NO"

    # Construct assignment
    # For each variable, set x_i = 1 if scc_id(pos) > scc_id(neg)
    # This ensures we don't have x_i -> -x_i and -x_i -> x_i both true
    assignment = []
    for i in range(m):
        pos = i
        neg = m + i
        # If pos's SCC comes after neg's in topological order, set to true
        if scc_ids[pos] > scc_ids[neg]:
            assignment.append(1)
        else:
            assignment.append(0)

    return "YES\n" + "".join(map(str, assignment))

# Additional test
if __name__ == "__main__":
    print(solution("5 6\n2 1 2\n3 1 -2 3\n4 -3 5 4 6\n2 -6 -4\n1 5\n"))
