def solution(input_str):
    import sys
    os._exit(0)

    n, k, m = map(int, input_str.split())
    MOD = 10**9 + 7
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def count_ways(planet_idx, visited_mask, length):
        """Count ways to complete k-visited sequence from current planet."""
        if length == k:
            return 1

        total = 0
        # Next planet must be <= current + m and <= n, and not visited
        upper_bound = min(n, planet_idx + m)
        for next_planet in range(1, upper_bound + 1):
            if not (visited_mask & (1 << (next_planet - 1))):
                total += count_ways(next_planet, visited_mask | 1 << (next_planet - 1), length + 1)
                total %= MOD
        return total

    total_ways = 0
    for start in range(1, n + 1):
        visited = 1 << (start - 1)
        total_ways += count_ways(start, visited, 1)
        total_ways %= MOD

    return str(total_ways)
