def solution(input_str):
    n, x = map(int, input_str.split())

    def is_prime_miller_rabin(n):
        """Miller-Rabin primality test"""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False

        d = n - 1
        r = 0
        while d % 2 == 0:
            d //= 2
            r += 1

        for a in [2, 3, 5, 7, 11, 13, 17, 19, 23]:
            if n <= a:
                break
            x = pow(a, d, n)
            if x == 1 or x == n - 1:
                continue
            for _ in range(r - 1):
                x = pow(x, 2, n)
                if x == n - 1:
                    break
            else:
                return False
        return True

    # The key insight: for a rotatable number of length n to exist in base b,
    # n+1 must be prime. This is derived from the properties of cyclic numbers.
    if not is_prime_miller_rabin(n + 1):
        return '-1\n'

    # We need b > 1, so x-1 must be at least 2
    b = x - 1
    if b < 2:
        return '-1\n'

    # b = x - 1 is always valid when n+1 is prime (since gcd(x-1, n+1) = 1)
    # except when x-1 is a multiple of n+1, but this is rare and b=x-1 works
    return f'{b}\n'
