def solve_2d_bracket(n: int, m: int, k: int, priorities: List[List[int]]) -> str:
    """
    Find the k-th correct 2D bracket array based on priority order.
    """
    # Get cells in priority order (minimum priority first = lexicographically first)
    cells = []
    for r in range(n):
        for c in range(m):
            cells.append((priorities[r][c], r, c))
    cells.sort()
    cell_order = [(r, c) for _, r, c in cells]

    # Result grid
    grid = [['' for _ in range(m)] for _ in range(n)]

    # Count bracket sequences from (r,c) to (n-1,m-1) that are valid
    # Using DP with balance state
    @lru_cache(maxsize=100000)
    def count_valid(r: int, c: int, balance: int, open_needed: int) -> int:
        """Count valid completions with given balance and open_needed pairs"""
        if r == n and c == m:
            return 1 if balance == 0 and open_needed == 0 else 0

        if balance < 0:
            return 0

        if r >= n or c >= m:
            return 0

        total_cells = (n - r) + (m - c)  # remaining cells
        if total_cells < balance:  # not enough cells to reach 0 balance
            return 0

        count = 0

        # Try both options and sum
        # Place '(' at current cell (if open_needed > 0)
        if open_needed > 0 and total_cells >= balance + 1:
            count += count_valid(r + 1, c, balance + 1, open_needed - 1)

        # Place ')' at current cell (if balance > 0)
        if balance > 0 and total_cells >= max(0, balance - 1):
            count += count_valid(r, c + 1, balance - 1, open_needed)

        return min(count, k + 10000000000)  # Cap to avoid huge numbers

    # Determine brackets cell by cell in priority order
    total_open = (n * m) // 2  # Half the cells must be '('
    current_open = 0
    current_balance = 0
    call_count = 0

