        call_count += 1

        # Binary search: try to place '(' and see if at least k completions exist
        open_needed = total_open - current_open
        total_rem = (n - r) + (m - c) - 1

        can_place_open = True
        if current_balance == 0 and open_needed == 0:
            can_place_open = False

        can_place_close = True
        if current_balance == 0:
            can_place_close = False

        count_if_open = 0
        count_if_close = 0

        if can_place_open:
            count_if_open = count_valid(r + 1, c, current_balance + 1, open_needed - 1)

        if can_place_close:
            count_if_close = count_valid(r, c + 1, current_balance - 1, open_needed)

        # Decide what to place
        if can_place_open and can_place_close:
            if k <= count_if_open:
                grid[r][c] = '('
                current_open += 1
                current_balance += 1
                k -= 1  # We already counted the current
            else:
                k -= count_if_open
                grid[r][c] = ')'
                current_balance -= 1
        elif can_place_open:
            grid[r][c] = '('
            current_open += 1
            current_balance += 1
        elif can_place_close:
            grid[r][c] = ')'
            current_balance -= 1
        else:
            grid[r][c] = '('  # Default if we must

    return '\n'.join([''.join(row) for row in grid])


