    # Build adjacency matrix where adj[i][j] = number of bridges between island i and j
    # Note: we have bridges only between different islands
    def build_adj_matrix():
        adj = [row[:] for row in [[0]*(n_islands+1) for _ in range(n_islands+1)]]
        for i in range(1, n_islands + 1):
            for j in range(1, n_islands + 1):
                if i != j:
                    g = gcd(i, j)
                    adj[i][j] = pow(2, g) % MOD
        return adj

    adj = build_adj_matrix()

    # B from home: home->i has a[i] bridges
    # Let dp[i][day] = ways to be at island i after 'day' days
    # dp[i][t] = a[i] + sum(dp[j][t-1] * adj[j][i]) for j=1..n_islands
    # Plus: staying at island i doesn't count as we need to start at some island after first move

    # Let total at island i at day t:
    # dp[i] = a[i]  (arrive from home and stay)
    #        + sum(adj[j][i] * dp[j]) for j != i
    #        + dp[i] * 1 (stay at same island)

    # For matrix M[i][j]:
    # M[i][j] = adj[j][i] for j != i
    # M[i][i] = 1 (stay option)
    # Initial vector V0 = [a[1], a[2], ..., a[n]] flipped since adj[j][i] means j->i

    # The transition for day t (after reaching initial island):
    # V[t] = V[0] * M^t

    # Build transition matrix T where T[j][i] = number of ways to go from j to i in one day
    T = [[0]*(n_islands+1) for _ in range(n_islands+1)]
    for j in range(1, n_islands+1):
        for i in range(1, n_islands+1):
            if i == j:
                T[j][i] = 1  # can stay
            else:
                T[j][i] = adj[j][i] % MOD  # move to i

    # Matrix multiplication
    def mat_mul(A, B):
        n = len(A)
        C = [[0]*n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if A[i][k]:
                    for j in range(n):
                        if B[k][j]:
                            C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def mat_pow(A, p):
        n = len(A)
        result = [[0]*n for _ in range(n)]
        for i in range(n):
            result[i][i] = 1
        base = [row[:] for row in A]
        while p > 0:
            if p & 1:
                result = mat_mul(result, base)
            base = mat_mul(base, base)
            p >>= 1
        return result

    # Initial state: after first move from home, you're at each island j with a[j] ways
    # V0[j] = a[j] (number of ways to reach island j after first move)
    # After t days: V[t] = V0 * T^t
    # But our matrix is T[j][i] = ways from j to i, so V[t][i] = sum over j of V0[j] * T[j][i]

    Tpower = mat_pow(T, t)

    # Compute final answer
    ans = [0]*(n_islands+1)
    for j in range(1, n_islands + 1):
        if a[j-1] > 0:
            for i in range(1, n_islands + 1):
