    from collections import deque

    results = {"min_ops": float('inf'), "ops": None}

    def bfs(s, t, path, n_ops):
        if check(s, t):
            if n_ops < results["min_ops"]:
                results["min_ops"] = n_ops
                results["ops"] = [(op_s[:], op_t[:]) for op_s, op_t in path]
            return

        if n_ops >= results["min_ops"]:
            return

        for i in range(len(s) + 1):
            for j in range(len(t) + 1):
                new_s = s[-i:] + t[:j]
                new_t = s[:len(s)-i] + t[j:]
                if check(new_s, new_t):
                    if n_ops + 1 < results["min_ops"]:
                        results["min_ops"] = n_ops + 1
                        results["ops"] = [(path[k][0] + (i,), path[k][1] + (j,)) for k in range(n_ops)]
                        break
                else:
