                    if check(new_s, new_t):
                        results["min_ops"] = n_ops + 1
                        results["ops"] = [(path[k][0] + (i,), path[k][1] + (j,)) for k in range(n_ops)]
                    else:
                        queue.append((new_s, new_t, new_ops))
        return results

    queue = deque([(s, t, [])])
    visited = set()
    states = [(s, t, [])]

    while states:
        curr_s, curr_t, ops = states.pop()

        if check(curr_s, curr_t):
            results["min_ops"] = len(ops)
            results["ops"] = ops
            break

        if len(ops) >= results["min_ops"]:
            continue

        for i in range(len(curr_s) + 1):
            for j in range(len(curr_t) + 1):
                new_s = curr_s[-i:] + curr_t[:j]
                new_t = curr_s[:len(curr_s)-i] + curr_t[j:]
                state = (new_s, new_t)
                if state not in visited:
                    visited.add(state)
                    states.append((new_s, new_t, ops + [(i, j)]))

