    # Center = (mid_x, mid_y) + t * (u_dx, u_dy)
    # Distance to circle center (cx, cy) = sqrt((cx - mid_x - t*u_dx)^2 + ...)

    best_r = math.sqrt(dist_sq(x1, y1, x2, y2))  # Initial upper bound

    # Try different approaches
