            if food[a] != 0 and food[b] != 0 and food[a] == food[b]:
                return False

        # Check no three consecutive have same food (including wraparound)
        for i in range(1, 2 * n + 1):
            c1 = i
            c2 = c1 % (2 * n) + 1
            c3 = c2 % (2 * n) + 1
            if food[c1] != 0 and food[c2] != 0 and food[c3] != 0:
                if food[c1] == food[c2] == food[c3]:
                    return False
        return True

    def backtrack(idx):
        if idx == 2 * n:
            return True

        pos = idx + 1
        for val in [1, 2]:
            food[pos] = val
            if check():
                if backtrack(idx + 1):
                    return True
            food[pos] = 0

        return False

    if backtrack(0):
        output = []
        for a, b in pairs:
            output.append(f"{food[a]} {food[b]}")
        return '\n'.join(output)
    else:
        return "-1"
