def solution(input_str):
    MOD = 1000000007

    lines = input_str.strip().split('\n')
    if not lines:
        return "0\n"

    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        points.append(tuple(parts))

    def normalize_direction(x, y):
        if x == 0 and y == 0:
            return (0, 0)
        g = math.gcd(abs(x), abs(y))
        x //= g
        y //= g
        if x < 0 or (x == 0 and y < 0):
            x = -x
            y = -y
        return (x, y)

    group_pairs = defaultdict(list)

    for i in range(n):
        x1, y1 = points[i]
        r2_1 = x1*x1 + y1*y1

        for j in range(i + 1, n):
            x2, y2 = points[j]
            r2_2 = x2*x2 + y2*y2

            # Circumcenter direction invariant for circle through O, P_i, P_j
            gx = r2_1*y2 - y1*r2_2
            gy = r2_2*x1 - x2*r2_1

            if gx == 0 and gy == 0:
                continue

            nx, ny = normalize_direction(gx, gy)
            group_pairs[(nx, ny)].append((i, j))

    ans = 0

    def count_k_matchings(edges, k):
        n_edges = len(edges)

        def backtrack(idx, used, cnt):
            if cnt == k:
                return 1
            if idx == n_edges or cnt > k:
                return 0

            total = 0
            u, v = edges[idx]

            # Include this edge
            if u not in used and v not in used:
                total += backtrack(idx + 1, used | {u, v}, cnt + 1)

            # Skip this edge
            total += backtrack(idx + 1, used, cnt)

            return total

        return backtrack(0, set(), 0)

    for group in group_pairs.values():
        m = len(group)
        if m < 2:
            continue

        # Sum over k >= 2 pairs
        for k in range(2, m + 1):
            count = count_k_matchings(group, k)
            if count > 0:
                ans = (ans + count) % MOD

    return str(ans) + "\n"
